import os


def read_file(root: str, name: str):
    root = os.path.realpath(root)
    path = os.path.realpath(os.path.join(root, name))
    if path != root and not path.startswith(root + os.sep):
        raise ValueError("path escapes root")
    with open(path) as f:
        return f.read()
